package org.delcom.ifs25019springbootcashflow.usecase;
import org.springframework.stereotype.Service; import org.delcom.ifs25019springbootcashflow.domain.*; import org.delcom.ifs25019springbootcashflow.domain.repository.*;
@Service public class AuthUseCase { private final IUserRepository users; public AuthUseCase(IUserRepository u){users=u;} public User ensureRootAdmin(String username,String password){String safeUsername=username==null||username.isBlank()?"admin":username.trim();String safePassword=password==null||password.isBlank()?"admin123":password;var existing=users.findByUsername(safeUsername);if(existing.isPresent())return existing.get();return users.save(new User(null,safeUsername,PasswordHasher.hash(safePassword),"Administrator",Role.ADMIN,null));} public User register(String username,String password,String name)throws DomainException{if(username==null||username.isBlank()||password==null||password.length()<6||name==null||name.isBlank())throw new ValidationException("Lengkapi data. Password minimal 6 karakter.");if(users.findByUsername(username.trim()).isPresent())throw new ValidationException("Username sudah digunakan.");return users.save(new User(null,username.trim(),PasswordHasher.hash(password),name.trim(),Role.USER,null));} public User login(String username,String password)throws DomainException{if(username==null||username.isBlank()||password==null||password.isBlank())throw new ValidationException("Username atau password salah.");User u=users.findByUsername(username).orElseThrow(()->new ValidationException("Username atau password salah."));if(!PasswordHasher.matches(password,u.passwordHash()))throw new ValidationException("Username atau password salah.");return u;} }
